  </main>

  <footer>
    <div class="wrap foot">
      <a href="#" class="logo"><i></i>Halo</a>
      <nav><a href="#">Confidentialité</a><a href="#">Conditions</a><a href="#">Contact</a></nav>
      <span>© 2026 Halo. Tous droits réservés.</span>
    </div>
  </footer>
</body>
</html>
