  .project:hover .frame { transform: scale(.985); }
  .f1 { background: radial-gradient(60% 70% at 30% 30%, #e8b48e, transparent 70%), linear-gradient(140deg, #b4532a, #3d1f12); }
  .f2 { background: radial-gradient(50% 60% at 70% 40%, #c9d6c1, transparent 70%), linear-gradient(160deg, #546a55, #1f2a20); }
  .f3 { background: linear-gradient(180deg, #e9e4d8 0 50%, #1a1814 50%); }
  .f3::after { content: "N°"; position: absolute; inset: auto 24px 24px auto; font-family: var(--display); font-size: 96px; color: #f4f1ea; line-height: 1; }
