        <a class="project narrow" href="#"><div class="frame f3"></div><div class="meta"><b>Numéro — Magazine</b><span>2025</span></div></a>
        <a class="project wide" href="#"><div class="frame f4"></div><div class="meta"><b>Kalo — Application</b><span>2024</span></div></a>
      </div>
    </section>

    <section id="services">
