  .logo i { width: 26px; height: 26px; border-radius: 8px; background: var(--lime); position: relative; }
  .logo i::after { content: ""; position: absolute; inset: 7px; border-radius: 50%; border: 2px solid var(--bg); border-right-color: transparent; }
  header nav { display: flex; gap: 28px; font-size: 14px; color: var(--muted); }
  header nav a:hover { color: var(--text); }
  .chip { height: 40px; padding: 0 18px; border-radius: 999px; border: 1px solid var(--line); display: inline-flex; align-items: center; font-size: 14px; }
