  .faces i:first-child { margin-left: 0; background: linear-gradient(135deg, #fbcfe8, #f472b6); }
  .faces i:nth-child(2) { background: linear-gradient(135deg, #bae6fd, #38bdf8); }
  .faces i:nth-child(3) { background: linear-gradient(135deg, #d9f99d, #84cc16); }

  /* Phone */
  .phone { justify-self: center; width: 300px; aspect-ratio: 9 / 19.2; border-radius: 46px; padding: 12px; background: linear-gradient(160deg, #2a2d36, #0c0d11); box-shadow: 0 0 0 1px #2c2f38, 0 60px 120px -40px rgba(0,0,0,.9), 0 0 80px -20px rgba(200,245,96,.25); position: relative; transform: rotate(-4deg); }
  .screen { height: 100%; border-radius: 36px; background: #0b0c10; overflow: hidden; padding: 46px 18px 18px; display: grid; align-content: start; gap: 14px; position: relative; }
  .screen::before { content: ""; position: absolute; top: 12px; left: 50%; transform: translateX(-50%); width: 92px; height: 26px; border-radius: 20px; background: #000; }
  .bal { padding: 18px; border-radius: 22px; background: linear-gradient(140deg, var(--lime), #8be04e); color: #0b0c10; }
  .bal small { font-size: 11px; opacity: .7; } .bal strong { display: block; font-size: 30px; letter-spacing: -.04em; line-height: 1.1; }
  .bal span { font-size: 11px; }
