  .row div { flex: 1; } .row small { display: block; color: var(--muted); font-size: 10px; }
  .row b { font-weight: 500; }
  .mini { display: flex; align-items: flex-end; gap: 5px; height: 64px; padding: 10px; border-radius: 14px; background: #14161c; }
  .mini i { flex: 1; border-radius: 4px; background: #2a2e38; }
