<style>
  :root { --bg: #ffffff; --ink: #111111; --muted: #737373; --line: #ececec; --soft: #f6f6f6; --dot: #22c55e; --sans: "Inter Tight", system-ui, sans-serif; --mono: "JetBrains Mono", ui-monospace, monospace; }
  * { box-sizing: border-box; margin: 0; }
