  .wrap { width: min(760px, 100% - 40px); margin-inline: auto; }
  .mono { font-family: var(--mono); font-size: 12px; letter-spacing: .02em; color: var(--muted); text-transform: uppercase; }

  header { display: flex; justify-content: space-between; align-items: center; padding: 40px 0 0; }
  .me { display: flex; align-items: center; gap: 14px; }
  .avatar { width: 44px; height: 44px; border-radius: 50%; background: radial-gradient(circle at 30% 30%, #fde68a, #f59e0b 45%, #7c2d12); }
  .me b { display: block; font-weight: 500; } .me span { font-size: 14px; color: var(--muted); }
  .status { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; padding: 6px 12px; border-radius: 999px; background: var(--soft); }
  .status i { width: 7px; height: 7px; border-radius: 50%; background: var(--dot); box-shadow: 0 0 0 4px rgba(34,197,94,.18); }

  .intro { padding: 88px 0 72px; }
  .intro h1 { font-size: clamp(30px, 4.6vw, 42px); line-height: 1.18; letter-spacing: -.03em; font-weight: 500; }
  .intro h1 span { color: var(--muted); }
  .links { margin-top: 28px; display: flex; flex-wrap: wrap; gap: 8px; }
  .links a { font-size: 14px; padding: 8px 14px; border-radius: 999px; border: 1px solid var(--line); transition: background .2s, border-color .2s; }
  .links a:hover { background: var(--soft); border-color: var(--soft); }

  section { padding: 40px 0; }
  .sec-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 20px; }

  .case { display: block; margin-bottom: 28px; }
  .case .img { aspect-ratio: 16 / 10; border-radius: 16px; overflow: hidden; background: var(--soft); position: relative; transition: transform .5s cubic-bezier(.2,.7,.2,1); }
  .case:hover .img { transform: translateY(-4px); }
  .img .ui { position: absolute; inset: 14% 12% -6%; border-radius: 12px 12px 0 0; background: #fff; box-shadow: 0 30px 60px -30px rgba(0,0,0,.35); padding: 16px; display: grid; gap: 10px; align-content: start; }
  .img .ui i { display: block; height: 10px; border-radius: 6px; background: var(--line); }
  .img .ui i.w60 { width: 60%; } .img .ui i.w40 { width: 40%; }
  .img .ui .blk { height: 90px; border-radius: 10px; }
  .g1 { background: linear-gradient(135deg, #dbeafe, #e0e7ff); } .g1 .blk { background: linear-gradient(120deg, #6366f1, #a5b4fc); }
  .g2 { background: linear-gradient(135deg, #dcfce7, #f0fdf4); } .g2 .blk { background: linear-gradient(120deg, #16a34a, #86efac); }
  .g3 { background: linear-gradient(135deg, #ffe4e6, #fff1f2); } .g3 .blk { background: linear-gradient(120deg, #e11d48, #fda4af); }
  .case-meta { display: flex; justify-content: space-between; gap: 16px; margin-top: 14px; }
  .case-meta b { font-weight: 500; } .case-meta span { color: var(--muted); font-size: 15px; }

  .timeline { border-top: 1px solid var(--line); }
  .job { display: grid; grid-template-columns: 140px 1fr auto; gap: 16px; padding: 18px 0; border-bottom: 1px solid var(--line); font-size: 15px; }
  .job span { color: var(--muted); }

  .skills { display: flex; flex-wrap: wrap; gap: 8px; }
  .skills span { font-size: 14px; padding: 6px 12px; border-radius: 8px; background: var(--soft); }

  .contact { margin: 40px 0 64px; padding: 40px; border-radius: 20px; background: var(--ink); color: #fff; }
  .contact h2 { font-size: 28px; letter-spacing: -.03em; font-weight: 500; line-height: 1.2; }
  .contact p { margin-top: 8px; color: #a3a3a3; }
  .contact a { margin-top: 24px; display: inline-flex; align-items: center; gap: 10px; height: 46px; padding: 0 20px; border-radius: 999px; background: #fff; color: var(--ink); font-weight: 500; transition: gap .25s; }
  .contact a:hover { gap: 16px; }
  footer { padding-bottom: 48px; display: flex; justify-content: space-between; }

  @media (max-width: 640px) { .job { grid-template-columns: 1fr; gap: 2px; } header { flex-wrap: wrap; gap: 16px; } }
</style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="me"><div class="avatar"></div><div><b>Inès Kaboré</b><span>Designer produit · Abidjan</span></div></div>
      <span class="status"><i></i>Disponible en novembre</span>
