      <a class="case" href="#"><div class="img g2"><div class="ui"><i class="w60"></i><i class="w40"></i><div class="blk"></div><i></i></div></div><div class="case-meta"><b>Wave — Transferts entre amis</b><span>Mobile · 4 M d'utilisateurs</span></div></a>
      <a class="case" href="#"><div class="img g3"><div class="ui"><div class="blk"></div><i></i><i class="w60"></i><i class="w40"></i></div></div><div class="case-meta"><b>Lumen — Système de design</b><span>120 composants · 6 équipes</span></div></a>
