('7e0c0000-0000-4000-8000-000000000402', NULL, 'Kit UI Nuit', 'Kit sombre en verre dépoli pour tableaux de bord et outils IA : boutons lumineux, zone de prompt, contrôles segmentés, statistiques et notifications.', 'ui_kit', $tn$<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kit UI Nuit</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
  /* Kit Nuit — surfaces sombres en verre dépoli, accent lumineux. Idéal pour tableaux de bord et outils IA. */
  :root {
    --bg: #09090b; --panel: rgba(255,255,255,.04); --panel-strong: rgba(255,255,255,.07); --line: rgba(255,255,255,.09);
    --text: #fafafa; --muted: #a1a1aa; --accent: #8b5cf6; --accent-2: #22d3ee; --success: #4ade80; --danger: #f87171;
    --r: 12px; --font: "Manrope", system-ui, sans-serif;
  }
  * { box-sizing: border-box; margin: 0; }
  body { min-height: 100vh; background: radial-gradient(900px 500px at 15% -10%, rgba(139,92,246,.25), transparent 60%), radial-gradient(700px 400px at 100% 0%, rgba(34,211,238,.14), transparent 60%), var(--bg); color: var(--text); font: 400 14px/1.55 var(--font); -webkit-font-smoothing: antialiased; padding: 48px 20px; }
  .sheet { width: min(1000px, 100%); margin: 0 auto; display: grid; gap: 20px; }
  .sheet > header h1 { font-size: 28px; font-weight: 700; letter-spacing: -.03em; }
  .sheet > header p { color: var(--muted); }
  .glass { background: var(--panel); border: 1px solid var(--line); border-radius: 18px; padding: 24px; backdrop-filter: blur(16px); }
  h2 { font-size: 12px; text-transform: uppercase; letter-spacing: .14em; color: var(--muted); font-weight: 600; margin-bottom: 16px; }
  .row { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
  .cols { display: grid; grid-template-columns: 1.2fr 1fr; gap: 20px; }

  .btn { height: 40px; padding: 0 18px; border-radius: var(--r); border: 1px solid transparent; font: 600 14px var(--font); color: var(--text); cursor: pointer; display: inline-flex; align-items: center; gap: 8px; transition: transform .15s, box-shadow .2s, background .2s; }
  .btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  .btn-glow { background: linear-gradient(135deg, var(--accent), #6d28d9); box-shadow: 0 0 0 1px rgba(255,255,255,.12) inset, 0 10px 30px -10px rgba(139,92,246,.8); }
  .btn-glow:hover { transform: translateY(-1px); box-shadow: 0 0 0 1px rgba(255,255,255,.18) inset, 0 14px 36px -10px rgba(139,92,246,.95); }
  .btn-glass { background: var(--panel-strong); border-color: var(--line); } .btn-glass:hover { background: rgba(255,255,255,.1); }
  .btn-outline { border-color: rgba(139,92,246,.6); color: #c4b5fd; background: rgba(139,92,246,.08); }
  .btn-icon { width: 40px; padding: 0; justify-content: center; }

  .input-wrap { display: flex; align-items: center; gap: 10px; height: 44px; padding: 0 14px; border-radius: var(--r); background: rgba(0,0,0,.35); border: 1px solid var(--line); transition: border-color .2s, box-shadow .2s; }
  .input-wrap:focus-within { border-color: rgba(139,92,246,.7); box-shadow: 0 0 0 4px rgba(139,92,246,.15); }
  .input-wrap input { flex: 1; min-width: 0; background: none; border: 0; outline: 0; color: var(--text); font: inherit; }
  .input-wrap input::placeholder { color: #71717a; }
  .input-wrap kbd { font: 600 11px var(--font); color: var(--muted); padding: 2px 7px; border-radius: 6px; border: 1px solid var(--line); }
  .prompt { border-radius: 16px; background: rgba(0,0,0,.35); border: 1px solid var(--line); padding: 14px; }
  .prompt textarea { width: 100%; min-height: 72px; resize: none; background: none; border: 0; outline: 0; color: var(--text); font: inherit; font-size: 15px; }
  .prompt .row { justify-content: space-between; }
  .chip { height: 30px; padding: 0 12px; border-radius: 999px; background: var(--panel-strong); border: 1px solid var(--line); font-size: 12px; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; }
  .chip.on { color: var(--text); border-color: rgba(34,211,238,.5); background: rgba(34,211,238,.1); }

  .stat { padding: 18px; border-radius: 14px; background: var(--panel); border: 1px solid var(--line); }
  .stat small { color: var(--muted); } .stat strong { display: block; font-size: 26px; font-weight: 700; letter-spacing: -.03em; }
  .up { color: var(--success); font-size: 12px; } .down { color: var(--danger); font-size: 12px; }
  .stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
  .progress { height: 8px; border-radius: 999px; background: rgba(255,255,255,.08); overflow: hidden; margin-top: 10px; }
  .progress i { display: block; height: 100%; width: 68%; border-radius: inherit; background: linear-gradient(90deg, var(--accent), var(--accent-2)); }

  .seg { display: inline-flex; padding: 4px; border-radius: 12px; background: rgba(0,0,0,.35); border: 1px solid var(--line); }
  .seg button { border: 0; background: none; color: var(--muted); font: 600 13px var(--font); padding: 7px 14px; border-radius: 9px; cursor: pointer; }
  .seg button[aria-selected="true"] { background: var(--panel-strong); color: var(--text); box-shadow: 0 0 0 1px var(--line) inset; }
  .toggle { width: 42px; height: 24px; border-radius: 999px; background: linear-gradient(135deg, var(--accent), var(--accent-2)); position: relative; }
  .toggle::after { content: ""; position: absolute; top: 3px; right: 3px; width: 18px; height: 18px; border-radius: 50%; background: #fff; }
  .toast { display: flex; gap: 12px; align-items: center; padding: 14px 16px; border-radius: 14px; background: rgba(24,24,27,.85); border: 1px solid var(--line); box-shadow: 0 20px 40px -20px rgba(0,0,0,.8); }
  .toast i { width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; background: rgba(74,222,128,.15); color: var(--success); font-style: normal; }
  .toast span { color: var(--muted); }
  @media (max-width: 820px) { .cols, .stats { grid-template-columns: 1fr; } }
</style>
</head>
<body>
  <main class="sheet">
    <header><h1>Kit UI Nuit</h1><p>Verre dépoli, contrastes doux et accents lumineux.</p></header>
    <section class="glass"><h2>Boutons</h2>
      <div class="row"><button class="btn btn-glow">Générer ✦</button><button class="btn btn-glass">Dupliquer</button><button class="btn btn-outline">Mettre à niveau</button><button class="btn btn-glass btn-icon" aria-label="Partager">↗</button></div>
    </section>
    <div class="cols">
      <section class="glass"><h2>Saisie</h2>
        <div style="display:grid;gap:14px">
          <div class="input-wrap"><span aria-hidden="true">⌕</span><input placeholder="Rechercher un projet…" aria-label="Rechercher"><kbd>⌘K</kbd></div>
          <div class="prompt"><textarea aria-label="Message" placeholder="Décrivez ce que vous voulez créer…"></textarea>
            <div class="row"><div class="row" style="gap:8px"><span class="chip on">◆ Raisonnement</span><span class="chip">+ Fichier</span></div><button class="btn btn-glow btn-icon" aria-label="Envoyer">↑</button></div>
          </div>
        </div>
      </section>
      <section class="glass"><h2>Contrôles</h2>
        <div style="display:grid;gap:18px">
          <div class="seg" role="tablist"><button role="tab" aria-selected="true">Jour</button><button role="tab" aria-selected="false">Semaine</button><button role="tab" aria-selected="false">Mois</button></div>
          <div class="row" style="justify-content:space-between"><span>Synchronisation automatique</span><span class="toggle" role="img" aria-label="Activé"></span></div>
          <div><div class="row" style="justify-content:space-between"><span>Quota utilisé</span><span style="color:var(--muted)">68 %</span></div><div class="progress"><i></i></div></div>
        </div>
      </section>
    </div>
    <section class="glass"><h2>Statistiques</h2>
      <div class="stats">
        <div class="stat"><small>Requêtes</small><strong>48 920</strong><span class="up">▲ 12,8 %</span></div>
        <div class="stat"><small>Latence moyenne</small><strong>182 ms</strong><span class="up">▲ 4,1 %</span></div>
        <div class="stat"><small>Erreurs</small><strong>0,21 %</strong><span class="down">▼ 0,05 pt</span></div>
      </div>
    </section>
    <div class="toast"><i>✓</i><div><b>Déploiement réussi</b><br><span>Votre site est en ligne depuis 12 secondes.</span></div></div>
  </main>
</body>
</html>
$tn$, 'html', 'TechNova', 'TechNova Studio', 'technova', true, true, true, false, 'public'),
('7e0c0000-0000-4000-8000-000000000501', NULL, 'Duo Éditorial — Instrument Serif × Inter', 'Serif contrasté pour les titres, linéale neutre pour le texte. Planche complète et CSS prêt à copier. Polices SIL OFL.', 'font', $tn$<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Duo typographique — Instrument Serif × Inter</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
<style>
  /* À copier dans votre projet :
     @import url("https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&family=Inter:wght@400;500;600&display=swap");
     :root { --font-display: "Instrument Serif", Georgia, serif; --font-body: "Inter", system-ui, sans-serif; }
     h1, h2 { font-family: var(--font-display); font-weight: 400; letter-spacing: -0.02em; line-height: 1; }
     body { font-family: var(--font-body); line-height: 1.6; }
     Licence : SIL Open Font License 1.1 (usage commercial autorisé). */
  :root { --display: "Instrument Serif", Georgia, serif; --body: "Inter", system-ui, sans-serif; --bg: #f8f7f4; --ink: #151412; --muted: #7a776f; --line: #e3e0d8; }
  * { box-sizing: border-box; margin: 0; }
  body { background: var(--bg); color: var(--ink); font: 400 16px/1.6 var(--body); -webkit-font-smoothing: antialiased; padding: 56px 24px; }
  .spec { width: min(1040px, 100%); margin: 0 auto; }
  .top { display: flex; justify-content: space-between; gap: 16px; font-size: 13px; color: var(--muted); border-bottom: 1px solid var(--line); padding-bottom: 16px; }
  .hero { font-family: var(--display); font-size: clamp(64px, 12vw, 176px); line-height: .9; letter-spacing: -.03em; margin: 48px 0 36px; }
  .hero em { color: #9a3412; }
  .pair { display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: var(--line); border: 1px solid var(--line); margin-top: 48px; }
  .pair > div { background: var(--bg); padding: 32px; }
  .pair small { font-size: 12px; text-transform: uppercase; letter-spacing: .14em; color: var(--muted); }
  .pair h3 { font-family: var(--display); font-weight: 400; font-size: 44px; line-height: 1; margin: 14px 0 10px; }
  .pair h3.sans { font-family: var(--body); font-weight: 600; font-size: 36px; letter-spacing: -.03em; }
  .alpha { font-size: 20px; letter-spacing: .02em; color: var(--muted); word-break: break-all; }
  .sample { display: grid; grid-template-columns: 1.1fr 1fr; gap: 56px; margin-top: 64px; align-items: start; }
  .sample h2 { font-family: var(--display); font-weight: 400; font-size: clamp(40px, 5vw, 64px); line-height: 1; letter-spacing: -.02em; }
  .sample p { color: #45423c; font-size: 17px; } .sample p + p { margin-top: 14px; }
  .scale { margin-top: 64px; border-top: 1px solid var(--line); }
  .scale div { display: grid; grid-template-columns: 90px 1fr; align-items: baseline; padding: 14px 0; border-bottom: 1px solid var(--line); }
  .scale span { font-size: 12px; color: var(--muted); }
  @media (max-width: 760px) { .pair, .sample { grid-template-columns: 1fr; } }
</style>
</head>
<body>
  <article class="spec">
    <div class="top"><span>Duo typographique · Éditorial</span><span>Instrument Serif × Inter</span></div>
    <p class="hero">L'élégance <em>tranquille.</em></p>
    <p style="color:var(--muted);max-width:520px">Un serif contrasté pour les titres, une linéale neutre pour le texte : l'accord idéal des marques premium, des magazines et des studios.</p>
    <div class="pair">
      <div><small>Titres</small><h3>Instrument Serif</h3><p class="alpha">Aa Bb Cc Dd Ee Ff Gg Hh Ii Jj Kk Ll Mm Nn Oo Pp 0123456789</p></div>
      <div><small>Texte</small><h3 class="sans">Inter</h3><p class="alpha">Aa Bb Cc Dd Ee Ff Gg Hh Ii Jj Kk Ll Mm Nn Oo Pp 0123456789</p></div>
    </div>
    <div class="sample">
      <h2>Ce qui compte vraiment se voit au premier regard.</h2>
      <div><p>Une bonne typographie ne se remarque pas : elle guide. Le serif apporte la voix, la personnalité et le rythme des grands titres.</p><p>Inter assure la lisibilité sur tous les écrans, des paragraphes longs aux interfaces les plus denses.</p></div>
    </div>
    <div class="scale">
      <div><span>Display 96</span><p style="font-family:var(--display);font-size:clamp(48px,7vw,96px);line-height:1">Saison</p></div>
      <div><span>H2 48</span><p style="font-family:var(--display);font-size:48px;line-height:1.05">Une histoire de détails</p></div>
      <div><span>H3 24 / 600</span><p style="font-weight:600;font-size:24px;letter-spacing:-.02em">Titre de carte</p></div>
      <div><span>Corps 16</span><p>Le texte courant reste confortable sur de longues lignes.</p></div>
      <div><span>Légende 13</span><p style="font-size:13px;color:var(--muted)">Légende, métadonnées et notes de bas de page.</p></div>
    </div>
  </article>
</body>
</html>
$tn$, 'html', 'fonts.google.com', 'TechNova Studio', 'ofl', true, true, true, false, 'public'),
('7e0c0000-0000-4000-8000-000000000502', NULL, 'Duo Technique — Space Grotesk × IBM Plex Mono', 'Grotesque géométrique et monospace rigoureuse pour produits tech, API et tableaux de bord. Polices SIL OFL.', 'font', $tn$<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Duo typographique — Space Grotesk × IBM Plex Mono</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
  /* À copier dans votre projet :
     @import url("https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap");
     :root { --font-sans: "Space Grotesk", system-ui, sans-serif; --font-mono: "IBM Plex Mono", ui-monospace, monospace; }
     h1, h2, h3 { font-family: var(--font-sans); font-weight: 600; letter-spacing: -0.04em; }
     code, .label, .data { font-family: var(--font-mono); }
     Licence : SIL Open Font License 1.1 (usage commercial autorisé). */
  :root { --sans: "Space Grotesk", system-ui, sans-serif; --mono: "IBM Plex Mono", ui-monospace, monospace; --bg: #0b0d0c; --ink: #e8efe9; --muted: #7d8a81; --line: #1f2622; --lime: #b6f36a; }
  * { box-sizing: border-box; margin: 0; }
  body { background: var(--bg); color: var(--ink); font: 400 16px/1.6 var(--sans); -webkit-font-smoothing: antialiased; padding: 56px 24px; }
  .spec { width: min(1040px, 100%); margin: 0 auto; }
  .mono { font-family: var(--mono); font-size: 12px; color: var(--muted); }
  .top { display: flex; justify-content: space-between; padding-bottom: 16px; border-bottom: 1px dashed var(--line); }
  .hero { font-size: clamp(56px, 11vw, 156px); font-weight: 700; letter-spacing: -.06em; line-height: .88; margin: 48px 0 20px; }
  .hero span { color: var(--lime); }
  .grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: var(--line); border: 1px solid var(--line); margin-top: 48px; }
  .grid div { background: var(--bg); padding: 22px; }
  .grid b { display: block; font-size: 34px; font-weight: 600; letter-spacing: -.04em; }
  .term { margin-top: 48px; border: 1px solid var(--line); border-radius: 14px; overflow: hidden; }
  .term header { display: flex; gap: 6px; padding: 12px 14px; border-bottom: 1px solid var(--line); }
  .term header i { width: 10px; height: 10px; border-radius: 50%; background: #2a332e; }
  .term pre { margin: 0; padding: 20px; font: 400 14px/1.8 var(--mono); color: #b9c6bd; overflow-x: auto; }
  .term .k { color: var(--lime); } .term .s { color: #f5d67b; } .term .c { color: #56625a; }
  .pair { display: grid; grid-template-columns: 1fr 1fr; gap: 48px; margin-top: 56px; }
  .pair h2 { font-size: 40px; font-weight: 600; letter-spacing: -.045em; line-height: 1.05; }
  .pair p { color: #a9b5ad; margin-top: 12px; }
  .alpha { margin-top: 18px; font-size: 18px; color: var(--muted); word-break: break-all; }
  @media (max-width: 760px) { .grid { grid-template-columns: 1fr 1fr; } .pair { grid-template-columns: 1fr; } }
</style>
</head>
<body>
  <article class="spec">
    <div class="top mono"><span>// duo typographique · technique</span><span>space_grotesk × ibm_plex_mono</span></div>
    <p class="hero">Build<br>things <span>fast.</span></p>
    <p style="max-width:520px;color:#a9b5ad">Une grotesque géométrique au caractère affirmé, accompagnée d'une monospace rigoureuse pour les données, le code et les libellés.</p>
    <div class="grid">
      <div><span class="mono">latence</span><b>38 ms</b></div>
      <div><span class="mono">uptime</span><b>99,99 %</b></div>
      <div><span class="mono">requêtes/s</span><b>12 400</b></div>
      <div><span class="mono">régions</span><b>14</b></div>
